import{_ as a,o,c as t,a2 as c}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Buenas prácticas","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/frontend/tailwind/09-buenas-practicas.md","filePath":"full-stack/frontend/tailwind/09-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),i={name:"full-stack/frontend/tailwind/09-buenas-practicas.md"};function r(s,e,d,n,l,u){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h1><p>Cierra el modelo: clases detectables, tokens, componentes, CSS a propósito, responsive, a11y, dark y un CSS de build <strong>honesto</strong>.</p><p>Documentación: <a href="https://tailwindcss.com/docs/detecting-classes-in-source-files" target="_blank" rel="noreferrer">detecting classes</a>, <a href="https://tailwindcss.com/docs/styling-with-utility-classes" target="_blank" rel="noreferrer">styling with utilities</a>, <a href="https://tailwindcss.com/docs/dark-mode" target="_blank" rel="noreferrer">dark mode</a>, <a href="https://tailwindcss.com/docs/editor-setup#class-sorting-with-prettier" target="_blank" rel="noreferrer">orden de clases con Prettier</a>.</p><h2 id="clases-estaticas" tabindex="-1">Clases estáticas <a class="header-anchor" href="#clases-estaticas" aria-label="Permalink to &quot;Clases estáticas&quot;">​</a></h2><p>El scanner es texto. Mapas de strings completos, no <code>bg-${variant}-500</code>. Si una librería en <code>node_modules</code> trae utilities, <code>@source</code>.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><p><code>w-[37rem]</code> o <code>bg-[#1a2b3c]</code> una vez: bien. Tres veces: <code>@theme</code> o variable. Arbitrary no es el theme.</p><h2 id="componentes-vs-css" tabindex="-1">Componentes vs CSS <a class="header-anchor" href="#componentes-vs-css" aria-label="Permalink to &quot;Componentes vs CSS&quot;">​</a></h2><p>Markup repetido + comportamiento → componente/template. CSS custom (<code>@layer</code>, <code>@utility</code>) cuando Tailwind no cubre el problema o hay que parchear un tercero. <code>@apply</code> no es la arquitectura (capítulo 5).</p><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><p>Base = móvil. <code>md:</code> / <code>lg:</code> = <strong>desde ese ancho</strong>. <code>@container</code> cuando el padre manda. Viewport meta.</p><h2 id="accesibilidad" tabindex="-1">Accesibilidad <a class="header-anchor" href="#accesibilidad" aria-label="Permalink to &quot;Accesibilidad&quot;">​</a></h2><p>Tailwind <strong>no</strong> resuelve:</p><ul><li>Contraste (<code>text-zinc-400</code> puede ser ilegal sobre blanco).</li><li>Semántica (<code>button</code> vs <code>div</code>).</li><li>Foco de teclado (<code>focus-visible:outline</code>).</li><li><code>disabled</code> real.</li><li><code>prefers-reduced-motion</code> (<code>motion-reduce:</code>).</li></ul><p>Un <code>hover:</code> sin <code>focus-visible:</code> deja el teclado a ciegas.</p><h2 id="dark-mode" tabindex="-1">Dark mode <a class="header-anchor" href="#dark-mode" aria-label="Permalink to &quot;Dark mode&quot;">​</a></h2><p>Cada fondo tiene texto y borde en <code>dark:</code>. Default = sistema; clase o <code>data-theme</code> = <code>@custom-variant</code> + script temprano (FOUC).</p><h2 id="orden-de-clases" tabindex="-1">Orden de clases <a class="header-anchor" href="#orden-de-clases" aria-label="Permalink to &quot;Orden de clases&quot;">​</a></h2><p>No discutan el orden a mano. El <a href="https://tailwindcss.com/docs/editor-setup#class-sorting-with-prettier" target="_blank" rel="noreferrer">plugin de Prettier oficial</a> las agrupa de forma estable. No es una regla de negocio.</p><h2 id="css-generado-performance" tabindex="-1">CSS generado (performance) <a class="header-anchor" href="#css-generado-performance" aria-label="Permalink to &quot;CSS generado (performance)&quot;">​</a></h2><p>Tailwind <strong>escanea</strong> y emite utilities usadas. En v4 no configuras <code>purge</code> ni <code>content: []</code> como receta diaria: la detección es automática (ajustable con <code>@source</code>).</p><p>Eso <strong>no</strong> significa “siempre el CSS mínimo imaginable”: safelist (<code>@source inline()</code>), CSS custom, y fuentes extra crecen el fichero. Habla de <strong>CSS de build acotado a lo detectado</strong>, no de milagros.</p><p>Play CDN y concatenación dinámica hacen lo contrario: o hinchan, o faltan clases.</p><h2 id="recetas-v3-que-este-manual-no-usa-como-camino-principal" tabindex="-1">Recetas v3 que este manual no usa como camino principal <a class="header-anchor" href="#recetas-v3-que-este-manual-no-usa-como-camino-principal" aria-label="Permalink to &quot;Recetas v3 que este manual no usa como camino principal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>v3</th><th>Ahora</th></tr></thead><tbody><tr><td><code>@tailwind base/components/utilities</code></td><td><code>@import &quot;tailwindcss&quot;</code></td></tr><tr><td><code>tailwind.config.js</code> + <code>theme.extend</code></td><td><code>@theme</code></td></tr><tr><td><code>content: [...]</code></td><td>detección + <code>@source</code> si hace falta</td></tr><tr><td><code>darkMode: &#39;class&#39;</code></td><td><code>@custom-variant dark (...)</code></td></tr><tr><td><code>npx tailwindcss init</code></td><td>plugin Vite / CLI v4</td></tr><tr><td><code>purge</code></td><td>no aplica como paso aparte</td></tr></tbody></table><p><code>@config</code> existe para <strong>migrar</strong>.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Theme flash por aplicar <code>.dark</code> después del primer paint.</li><li>Optimizar el orden de clases y olvidar el contraste.</li><li>Copiar un config JS enorme “por si el v4 lo necesita”.</li></ul><h2 id="buenas-practicas-1" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas-1" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>CSS-first; utilities en el markup; tokens cuando se repiten.</li><li>Probar light, dark, teclado, y un viewport estrecho.</li><li>La doc oficial es el catálogo de utilities; este manual es el modelo mental.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Busca concatenaciones dinámicas en tu repo y sustituye por mapas.</li><li>Activa Prettier + plugin y deja de ordenar clases a ojo.</li><li>Relee 01–08 y marca cada decisión: token, componente o CSS suelto.</li></ol><p>Fin del manual Tailwind.</p>',33)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
